package com.shiphappens.logistics.entity;
import jakarta.persistence.*;
@Entity @Table(name="drivers") public class Driver { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="driver_code") private String driverCode; private String name,phone; @Column(name="license_number") private String licenseNumber; @Enumerated(EnumType.STRING) private Statuses.DriverStatus status=Statuses.DriverStatus.AVAILABLE; public Long getId(){return id;} public String getDriverCode(){return driverCode;} public void setDriverCode(String v){driverCode=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getLicenseNumber(){return licenseNumber;} public void setLicenseNumber(String v){licenseNumber=v;} public Statuses.DriverStatus getStatus(){return status;} public void setStatus(Statuses.DriverStatus v){status=v;} }
